<?php
namespace App\Http\Controllers;
use App\Models\{Event, Facility, Region, SiteSetting, Sport, SportCategory, Testimonial, Inquiry};
use Illuminate\Http\Request;
use Illuminate\Support\Str;
use Inertia\Inertia;

class AdminController extends Controller
{
    public function __construct() { $this->middleware('auth'); }
    public function dashboard() { return Inertia::render('admin/dashboard', ['stats' => ['facilities' => Facility::count(), 'sports' => Sport::count(), 'events' => Event::where('published', true)->count(), 'inquiries' => Inquiry::where('status', 'new')->count()], 'recentEvents' => Event::with('sport')->latest()->take(5)->get()]); }
    public function content() { return Inertia::render('admin/content', ['facilities' => Facility::with('sports')->latest()->get(), 'sports' => Sport::latest()->get(), 'events' => Event::with(['sport', 'facility'])->latest()->get(), 'regions' => Region::orderBy('name')->get(), 'categories' => SportCategory::orderBy('name')->get()]); }
    public function storeSport(Request $request) { $data = $request->validate(['name' => ['required', 'max:120'], 'description' => ['nullable'], 'surface' => ['nullable', 'max:120'], 'court_type' => ['nullable', 'max:120'], 'sport_category_id' => ['nullable', 'exists:sport_categories,id'], 'image' => ['nullable', 'image', 'max:5120']]); $data['slug'] = Str::slug($data['name']); $data['image'] = $this->image($request, 'image', $data['image'] ?? null); Sport::create($data + ['published' => true]); return back()->with('success', 'Sport berhasil dibuat.'); }
    public function updateSport(Request $request, Sport $sport) { $data = $request->validate(['name' => ['required', 'max:120'], 'description' => ['nullable'], 'surface' => ['nullable', 'max:120'], 'court_type' => ['nullable', 'max:120'], 'sport_category_id' => ['nullable', 'exists:sport_categories,id'], 'published' => ['boolean']]); $data['slug'] = Str::slug($data['name']); $sport->update($data); return back()->with('success', 'Sport diperbarui.'); }
    public function destroySport(Sport $sport) { $sport->delete(); return back()->with('success', 'Sport dihapus.'); }
    public function storeFacility(Request $request) { $data = $request->validate(['name' => ['required', 'max:160'], 'description' => ['nullable'], 'subtitle' => ['nullable', 'max:160'], 'address' => ['nullable', 'max:255'], 'venue_type' => ['nullable', 'max:120'], 'capacity' => ['nullable', 'max:120'], 'operating_hours' => ['nullable', 'max:120'], 'region_id' => ['nullable', 'exists:regions,id'], 'sports' => ['array'], 'sports.*' => ['exists:sports,id'], 'hero_image' => ['nullable', 'image', 'max:5120']]); $data['slug'] = Str::slug($data['name']); $data['hero_image'] = $this->image($request, 'hero_image'); $data['thumbnail'] = $data['hero_image']; $sports = $data['sports'] ?? []; unset($data['sports']); $facility = Facility::create($data + ['published' => true]); $facility->sports()->sync($sports); return back()->with('success', 'Fasilitas berhasil dibuat.'); }
    public function updateFacility(Request $request, Facility $facility) { $data = $request->validate(['name' => ['required', 'max:160'], 'description' => ['nullable'], 'subtitle' => ['nullable', 'max:160'], 'address' => ['nullable', 'max:255'], 'venue_type' => ['nullable', 'max:120'], 'capacity' => ['nullable', 'max:120'], 'operating_hours' => ['nullable', 'max:120'], 'region_id' => ['nullable', 'exists:regions,id'], 'sports' => ['array'], 'sports.*' => ['exists:sports,id'], 'published' => ['boolean'], 'hero_image' => ['nullable', 'image', 'max:5120']]); $data['slug'] = Str::slug($data['name']); $image = $this->image($request, 'hero_image'); if ($image) { $data['hero_image'] = $image; $data['thumbnail'] = $image; } $sports = $data['sports'] ?? []; unset($data['sports']); $facility->update($data); $facility->sports()->sync($sports); return back()->with('success', 'Fasilitas diperbarui.'); }
    public function destroyFacility(Facility $facility) { $facility->delete(); return back()->with('success', 'Fasilitas dihapus.'); }
    public function storeEvent(Request $request) { $data = $request->validate(['title' => ['required', 'max:180'], 'description' => ['nullable'], 'sport_id' => ['nullable', 'exists:sports,id'], 'facility_id' => ['nullable', 'exists:facilities,id'], 'starts_at' => ['required', 'date'], 'ends_at' => ['nullable', 'date', 'after_or_equal:starts_at'], 'status' => ['required', 'in:draft,upcoming,ongoing,completed,cancelled'], 'published' => ['boolean'], 'image' => ['nullable', 'image', 'max:5120']]); $data['slug'] = Str::slug($data['title'].'-'.now()->format('YmdHis')); $data['image'] = $this->image($request, 'image'); Event::create($data); return back()->with('success', 'Event berhasil dibuat.'); }
    public function updateEvent(Request $request, Event $event) { $data = $request->validate(['title' => ['required', 'max:180'], 'description' => ['nullable'], 'sport_id' => ['nullable', 'exists:sports,id'], 'facility_id' => ['nullable', 'exists:facilities,id'], 'starts_at' => ['required', 'date'], 'ends_at' => ['nullable', 'date', 'after_or_equal:starts_at'], 'status' => ['required', 'in:draft,upcoming,ongoing,completed,cancelled'], 'published' => ['boolean']]); $event->update($data); return back()->with('success', 'Event diperbarui.'); }
    public function destroyEvent(Event $event) { $event->delete(); return back()->with('success', 'Event dihapus.'); }
    public function settings(Request $request) { $data = $request->validate(['site_name' => ['required', 'max:120'], 'tagline' => ['nullable', 'max:255'], 'address' => ['nullable', 'max:255'], 'phone' => ['nullable', 'max:40'], 'whatsapp' => ['nullable', 'max:40'], 'email' => ['nullable', 'email'], 'instagram' => ['nullable', 'max:120']]); foreach ($data as $key => $value) SiteSetting::updateOrCreate(['key' => $key], ['value' => $value]); return back()->with('success', 'Pengaturan disimpan.'); }
    private function image(Request $request, string $key, ?string $fallback = null): ?string { return $request->hasFile($key) ? $request->file($key)->store('ggm', 'public') : $fallback; }
}
